const $=s=>document.querySelector(s);const isoNow=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const nowISO=isoNow();const dateAt=offset=>new Date(Date.parse(state.start+'T00:00:00Z')+offset*86400000);const iso=d=>d.toISOString().slice(0,10);const md=d=>`${d.getUTCMonth()+1}.${d.getUTCDate()}`;const daysFromStart=()=>Math.floor((Date.parse(nowISO+'T00:00:00Z')-Date.parse(state.start+'T00:00:00Z'))/86400000);let selected=0;function selectCurrent(){const n=daysFromStart();state.week=Math.min(8,Math.max(1,Math.floor(n/7)+1));selected=n<0?0:n>=56?6:n%7}selectCurrent();const weekSelect=$('#week');for(let i=1;i<=8;i++)weekSelect.add(new Option(`${i}주차`,i));
