function render(){weekSelect.value=state.week;const offset=(state.week-1)*7;const d=days[selected],selectedDate=dateAt(offset+selected);$('#date-range').textContent=`${md(dateAt(offset))} — ${md(dateAt(offset+6))}`;$('#today-date').textContent=`${nowISO.replaceAll('-','.')} · ${['일','월','화','수','목','금','토'][new Date(nowISO+'T00:00:00Z').getUTCDay()]}요일`;const tabs=$('.days');tabs.replaceChildren();days.forEach((day,i)=>{const date=dateAt(offset+i);const b=document.createElement('button');b.className='day';b.id=`day-${i}`;b.setAttribute('role','tab');b.setAttribute('aria-selected',i===selected);b.setAttribute('aria-controls','today-panel');b.setAttribute('aria-label',`${md(date)} ${day.day}요일 ${day.time}분`);b.tabIndex=i===selected?0:-1;b.innerHTML=`<span class="weekday">${day.day}</span><span class="date">${date.getUTCDate()}</span><span class="dot"></span>`;b.classList.toggle('actual',iso(date)===nowISO);b.onclick=()=>{selected=i;render()};b.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%7;if(e.key==='ArrowLeft')n=(i+6)%7;if(e.key==='Home')n=0;if(e.key==='End')n=6;if(n!==undefined){e.preventDefault();selected=n;render();$(`#day-${n}`).focus()}};tabs.append(b)});$('#today-panel').setAttribute('aria-labelledby',`day-${selected}`);$('#selected-date').textContent=`${iso(selectedDate)===nowISO?'오늘 할 일':'선택한 날의 할 일'} · ${md(selectedDate)} ${d.day}요일`;$('#day-title').textContent=d.name;$('#day-time').textContent=`${d.time}분`;$('#topic').textContent=state.topics[state.week]||topics[state.week-1];const tasks=$('#tasks');tasks.replaceChildren();d.tasks.forEach((t,j)=>{const id=`${state.week}-${selected}-${j}`;const label=document.createElement('label');label.className='task';label.innerHTML=`<input type="checkbox"><span class="task-body"><span class="task-title">${t[0]}</span><small>${t[2]}</small></span><span class="task-time">${t[1]}분</span>`;const input=label.querySelector('input');input.checked=Boolean(state.checks[id]);input.onchange=()=>{state.checks[id]=input.checked;persist();updateMetrics()};tasks.append(label)});const noteKey=`${state.week}-${selected}`;$('#daily-note').value=typeof state.notes[noteKey]==='string'?state.notes[noteKey]:'';$('#daily-note').oninput=e=>{state.notes[noteKey]=e.target.value;persist()};const upcoming=$('#upcoming');upcoming.replaceChildren();let added=0;for(let n=offset+selected+1;n<56&&added<3;n++){const day=n%7,w=Math.floor(n/7)+1;if(checkedCount(w,day)===days[day].tasks.length)continue;const row=document.createElement('div');row.className='next-row';const title=day===1?'Preply 수업':day===3?'Ringle 수업':days[day].name;row.innerHTML=`<span class="next-date">${md(dateAt(n))} ${days[day].day}</span><div><b>${title}</b><small>${day===1?'준비 10 · 수업 50 · 복습 15분':day===3?'준비 10 · 수업 40 · 복습 15분':days[day].tasks.map(t=>t[0]).join(' · ')}</small></div><span>${days[day].time}분</span>`;upcoming.append(row);added++}if(!added)upcoming.textContent='이후 예정된 루틴이 없습니다.';document.querySelectorAll('[data-phase]').forEach(b=>b.classList.toggle('active',Math.floor((Number(b.dataset.phase)-1)/2)===Math.floor((state.week-1)/2)));updateMetrics()}
weekSelect.onchange=()=>{state.week=Number(weekSelect.value);render()};document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{state.week=Number(b.dataset.phase);render()});document.querySelectorAll('[data-view]').forEach(b=>{if(b.tagName!=='BUTTON')return;b.onclick=()=>{document.querySelector('.dashboard').dataset.view=b.dataset.view;document.querySelectorAll('.mobile-tabs button').forEach(t=>t.setAttribute('aria-selected',t===b))}});let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=async()=>{const text=prompts[b.dataset.prompt];try{await navigator.clipboard.writeText(text);toast('요청문을 복사했어요.')}catch{$('#copy-text').value=text;$('#copy-dialog').showModal();$('#copy-text').select()}});$('#copy-close').onclick=()=>$('#copy-dialog').close();$('#guide-open').onclick=()=>$('#guide').showModal();$('#guide-close').onclick=()=>$('#guide').close();$('#settings-open').onclick=()=>{$('#start-date').value=state.start;$('#settings-error').textContent='';$('#settings').showModal()};$('#settings-save').onclick=e=>{const start=$('#start-date').value;if(!start)return;if(new Date(start+'T00:00:00Z').getUTCDay()!==1){e.preventDefault();$('#settings-error').textContent='주간 루틴에 맞게 월요일을 선택하세요.';return}state.start=start;persist();selectCurrent();render()};$('#edit-topic').onclick=()=>{$('#topic-input').value=state.topics[state.week]||topics[state.week-1];$('#topic-dialog').showModal()};$('#topic-save').onclick=e=>{const s=$('#topic-input').value.trim();if(!s){e.preventDefault();$('#topic-input').setCustomValidity('주제를 입력하세요.');$('#topic-input').reportValidity();return}state.topics[state.week]=s;persist();render()};$('#topic-input').oninput=e=>e.target.setCustomValidity('');render();if(!storageOK)$('#save-state').textContent='저장소 확인 필요';
